          "evidence": [
            {"ref": "L06", "quote": "晉紀曰經正直不忠於我故誅之按傅畼干寳所記"},
            {"ref": "L07", "quote": "故二家之言深得之"}
          ]
        }
      ],
      "unanswered_aspects": [
        {
          "aspect_id": "Q1-U1",
          "gap": "王经被收的具体罪名与司法程序（'𬒳收'是因曹髦事败还是被司马昭事后追究）仍不明确，导致对'助魏不忠於晉'是直接指控还是事后追述的理解仍受影响。",
          "reading_impact": "medium"
        }
      ],
